options.script:
// === F1 TRACK MAP VISUALIZATION ===
// This script processes InfluxDB data to render:
// 1. Track outline (from track_layout measurement)
// 2. Player car trail (color-coded by brake intensity)
// 3. Rival car trail
// 4. Current car position markers

var traces = [];

// --- PARSE DATA FROM GRAFANA ---
var trackX = [], trackY = [];
var playerX = [], playerY = [], playerBrake = [], playerThrottle = [];
var rivalX = [], rivalY = [], rivalBrake = [];

if (data.series) {
  data.series.forEach(function(series) {
    var name = (series.name || '').toLowerCase();
    var fields = {};
    series.fields.forEach(function(f) {
      fields[f.name] = f.values;
    });

    if (name.indexOf('track_layout') >= 0 || name.indexOf('layout') >= 0) {
      trackX = fields['x'] || fields['world_x'] || [];
      trackY = fields['y'] || fields['world_z'] || [];
    } else if (name.indexOf('player') >= 0 || name.indexOf('Player') >= 0) {
      playerX = fields['world_x'] || fields['x'] || [];
      playerY = fields['world_z'] || fields['y'] || [];
      playerBrake = fields['brake'] || [];
      playerThrottle = fields['throttle'] || [];
    } else if (name.indexOf('rival') >= 0 || name.indexOf('Rival') >= 0) {
      rivalX = fields['world_x'] || fields['x'] || [];
      rivalY = fields['world_z'] || fields['y'] || [];
      rivalBrake = fields['brake'] || [];
    }
  });
}

// --- TRACK OUTLINE ---
if (trackX.length > 0) {
  traces.push({
    x: trackX,
    y: trackY,
    type: 'scatter',
    mode: 'lines',
    name: 'Track',
    line: { color: 'rgba(60, 60, 80, 0.8)', width: 12, shape: 'spline' },
    hoverinfo: 'skip'
  });
  // Track edge highlight
  traces.push({
    x: trackX,
    y: trackY,
    type: 'scatter',
    mode: 'lines',
    name: 'Track Edge',
    showlegend: false,
    line: { color: 'rgba(100, 100, 140, 0.4)', width: 14, shape: 'spline' },
    hoverinfo: 'skip'
  });
}

// --- PLAYER TRAIL (color by brake/throttle) ---
if (playerX.length > 0) {
  var colors = [];
  for (var i = 0; i < playerX.length; i++) {
    var b = playerBrake[i] || 0;
    var t = playerThrottle[i] || 0;
    if (b > 0.1) {
      // Red for braking (intensity based)
      var r = Math.min(255, Math.floor(150 + b * 105));
      colors.push('rgb(' + r + ',30,30)');
    } else if (t > 0.9) {
      colors.push('rgb(0,200,80)');  // Green for full throttle
    } else {
      colors.push('rgb(0,150,255)');  // Blue for coasting
    }
  }

  traces.push({
    x: playerX,
    y: playerY,
    type: 'scatter',
    mode: 'markers',
    name: 'Player Trail',
    marker: { color: colors, size: 3, opacity: 0.6 },
    hovertemplate: 'Brake: %{text}<extra>Player</extra>',
    text: playerBrake.map(function(b) { return (b * 100).toFixed(0) + '%'; })
  });

  // Current position (large marker)
  var lastIdx = playerX.length - 1;
  traces.push({
    x: [playerX[lastIdx]],
    y: [playerY[lastIdx]],
    type: 'scatter',
    mode: 'markers+text',
    name: 'Player',
    marker: { color: '#00e5ff', size: 14, symbol: 'circle',
              line: { color: '#fff', width: 2 } },
    text: ['P'],
    textposition: 'top center',
    textfont: { color: '#00e5ff', size: 12, family: 'Inter' }
  });
}

// --- RIVAL TRAIL ---
if (rivalX.length > 0) {
  traces.push({
    x: rivalX,
    y: rivalY,
    type: 'scatter',
    mode: 'markers',
    name: 'Rival Trail',
    marker: { color: 'rgba(255,165,0,0.4)', size: 3 },
    hoverinfo: 'skip'
  });

  var rLastIdx = rivalX.length - 1;
  traces.push({
    x: [rivalX[rLastIdx]],
    y: [rivalY[rLastIdx]],
    type: 'scatter',
    mode: 'markers+text',
    name: 'Rival',
    marker: { color: '#ff6600', size: 14, symbol: 'circle',
              line: { color: '#fff', width: 2 } },
    text: ['R'],
    textposition: 'top center',
    textfont: { color: '#ff6600', size: 12, family: 'Inter' }
  });
}

return {
  data: traces,
  layout: {
    autosize: true,
    paper_bgcolor: 'rgba(0,0,0,0)',
    plot_bgcolor: 'rgba(15,15,25,1)',
    font: { color: '#aaa', family: 'Inter, sans-serif', size: 11 },
    margin: { l: 20, r: 20, t: 10, b: 20 },
    xaxis: { showgrid: false, zeroline: false, showticklabels: false, scaleanchor: 'y', scaleratio: 1 },
    yaxis: { showgrid: false, zeroline: false, showticklabels: false },
    showlegend: true,
    legend: { x: 0.01, y: 0.99, bgcolor: 'rgba(0,0,0,0.6)', font: { color: '#ccc', size: 10 } },
    dragmode: false
  },
  config: { displayModeBar: false, responsive: true }
};
